            // if the next arg is optional
            if ((i >= minimum) && (optional || (i > 0))) {
                buffer.append('[');
            }

            if (bracketed) {
                buffer.append('<');
            }

            // add name
            buffer.append(name);
            ++i;

            // if numbering
            if (numbered) {
                buffer.append(i);
            }

            if (bracketed) {
                buffer.append('>');
            }
        }

        // if infinite args are allowed
        if (maximum == Integer.MAX_VALUE) {
            // append elipsis
            buffer.append(" ...");
        }

        // for each argument
